export class V22 extends HeyApiClient {
    /**
     * Get Order
     *
     * Get a swap quote and assembled transaction. This is the default happy path with all Ultra benefits
     * (predictive execution, RTSE, Jupiter Beam, gasless, multi-router competition).
     *
     * Without optional parameters, all routers compete for the best price (Metis, JupiterZ RFQ, Dflow, OKX).
     * Setting `payer` to a wallet different from `taker` restricts routing to Metis.
     *
     */
    public getOrder<ThrowOnError extends boolean = false>(options: Options<GetSwapV2OrderData, ThrowOnError>): RequestResult<GetSwapV2OrderResponses, GetSwapV2OrderErrors, ThrowOnError> {
        return (options.client ?? this.client).get<GetSwapV2OrderResponses, GetSwapV2OrderErrors, ThrowOnError>({
            security: [{
                    key: 'SwapV2_ApiKeyAuth',
                    name: 'x-api-key',
                    type: 'apiKey'
                }],
            url: '/swap/v2/order',
            ...options
        });
    }
    
    /**
     * Build Transaction
     *
     * Get a swap quote with raw instructions for building custom transactions.
     * This is the advanced path for integrators who need full transaction control
     * (add custom instructions, CPI, custom payer).
     *
     * You are responsible for assembling the transaction, signing, and sending via your own RPC.
     * The `/execute` endpoint is not available for `/build` transactions.
     *
     * Routing is Metis only. No swap fees are charged by Jupiter.
     *
     */
    public getBuild<ThrowOnError extends boolean = false>(options: Options<GetSwapV2BuildData, ThrowOnError>): RequestResult<GetSwapV2BuildResponses, GetSwapV2BuildErrors, ThrowOnError> {
        return (options.client ?? this.client).get<GetSwapV2BuildResponses, GetSwapV2BuildErrors, ThrowOnError>({
            security: [{
                    key: 'SwapV2_ApiKeyAuth',
                    name: 'x-api-key',
                    type: 'apiKey'
                }],
            url: '/swap/v2/build',
            ...options
        });
    }
    
    /**
     * Execute Transaction
     *
     * Execute a signed transaction from `/order`. Handles transaction landing, confirmation, and retry.
     *
     * Only available for transactions obtained via `/order`. Transactions built via `/build` must be
     * sent through your own RPC.
     *
     */
    public postExecute<ThrowOnError extends boolean = false>(options: Options<PostSwapV2ExecuteData, ThrowOnError>): RequestResult<PostSwapV2ExecuteResponses, PostSwapV2ExecuteErrors, ThrowOnError> {
        return (options.client ?? this.client).post<PostSwapV2ExecuteResponses, PostSwapV2ExecuteErrors, ThrowOnError>({
            security: [{
                    key: 'SwapV2_ApiKeyAuth',
                    name: 'x-api-key',
                    type: 'apiKey'
                }],
            url: '/swap/v2/execute',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
}

